package io.reactivex.rxjava4.internal.schedulers;

import java.io.Serial;
import java.util.*;
import java.util.concurrent.*;
import java.util.concurrent.atomic.*;

import io.reactivex.rxjava4.annotations.NonNull;
import io.reactivex.rxjava4.core.Scheduler;
import io.reactivex.rxjava4.core.Scheduler.Worker;
import io.reactivex.rxjava4.exceptions.*;

/**
 * Represents the state for a Scheduler -&gt; ExecutorService interface.
 * @param scheduler the scheduler to use
 * @param workerStore hosts the worker state
 * @since 4.0.0
 */
public record SchedulerToExecutorService(@NonNull Scheduler scheduler,
        @NonNull AtomicReference<Worker> workerStore) implements ExecutorService {

    @Override
    public void execute(Runnable command) {
        if (workerStore.get() instanceof Worker w) {
            w.schedule(command);
        } else {
            scheduler.scheduleDirect(command);
        }
    }

    @Override
    public void shutdown() {
        if (workerStore.get() instanceof Worker w) {
            w.dispose();
        } else {
            // FIXME, generally we don't want to shut down RxJava schedulers like this!
            // scheduler.shutdown();
            var w = workerStore.getAndSet(Scheduler.Worker.SHUTDOWN);
            if (w != null) {
                w.dispose();
            }
        }
    }

    @Override
    public List<Runnable> shutdownNow() {
        if (workerStore.get() instanceof Worker w) {
            w.dispose();
        } else {
            // FIXME, generally we don't want to shut down RxJava schedulers like this!
            // scheduler.shutdown();
            var w = workerStore.getAndSet(Scheduler.Worker.SHUTDOWN);
            if (w != null) {
                w.dispose();
            }
        }
        return List.of();
    }

    @Override
    public boolean isShutdown() {
        var w = workerStore.get();
        return w != null && w.isDisposed();
    }

    @Override
    public boolean isTerminated() {
        return isShutdown();
    }

    @Override
    public boolean awaitTermination(long timeout, TimeUnit unit) throws InterruptedException {
        // FIXME no idea how to passively wait, not really applicable in Rx
        long timeoutNanos = unit.toNanos(timeout);
        if (isTerminated()) {
            return true;
        }
        if (timeoutNanos <= 0) {
            return false;
        }

        long start = System.nanoTime();
        for (;;) {
            if (isTerminated()) {
                return true;
            }

            long elapsed = System.nanoTime() - start;
            long remaining = timeoutNanos - elapsed;
            if (remaining <= 0) {
                return isTerminated();
            }

            // There is no termination signal to await, so poll at a short interval.
            TimeUnit.NANOSECONDS.sleep(Math.min(remaining, TimeUnit.MILLISECONDS.toNanos(1)));
        }
    }

    @Override
    public <T> Future<T> submit(Callable<T> task) {
        return CompletableFuture.supplyAsync(() -> {
            try {
                return task.call();
            } catch (Throwable ex) {
                Exceptions.throwIfFatal(ex);
                throw Exceptions.propagate(ex);
            }
        }, this::execute);
    }

    @Override
    public <T> Future<T> submit(Runnable task, T result) {
        return CompletableFuture.supplyAsync(() -> {
            try {
                task.run();
                return result;
            } catch (Throwable ex) {
                Exceptions.throwIfFatal(ex);
                throw Exceptions.propagate(ex);
            }
        }, this::execute);
    }

    @Override
    public Future<?> submit(Runnable task) {
        return CompletableFuture.runAsync(() -> {
            try {
                task.run();
            } catch (Throwable ex) {
                Exceptions.throwIfFatal(ex);
                throw Exceptions.propagate(ex);
            }
        }, this::execute);
